CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE plugin_publisher(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,name text NOT NULL,classification text NOT NULL,provenance jsonb NOT NULL,status text NOT NULL DEFAULT 'unverified',verified_by uuid,verified_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,name));
CREATE TABLE plugin(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,publisher_id uuid NOT NULL,canonical_name text NOT NULL,display_name text NOT NULL,classification text NOT NULL,status text NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,canonical_name),FOREIGN KEY(publisher_id,tenant_id) REFERENCES plugin_publisher(id,tenant_id));
CREATE TABLE plugin_version(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plugin_id uuid NOT NULL,version text NOT NULL,manifest jsonb NOT NULL,manifest_digest text NOT NULL,status text NOT NULL DEFAULT 'submitted',submitted_by uuid NOT NULL,reviewed_by uuid,reviewed_at timestamptz,published_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,plugin_id,version),FOREIGN KEY(plugin_id,tenant_id) REFERENCES plugin(id,tenant_id));
CREATE TABLE capability_category(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,key text NOT NULL,name text NOT NULL,status text NOT NULL DEFAULT 'active',UNIQUE(id,tenant_id),UNIQUE(tenant_id,key));
CREATE TABLE capability_declaration(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plugin_version_id uuid NOT NULL,category_id uuid NOT NULL,capability_key text NOT NULL,purpose text NOT NULL,input_schema jsonb NOT NULL,output_schema jsonb NOT NULL,errors jsonb NOT NULL,side_effects jsonb NOT NULL,permissions jsonb NOT NULL,approval_mode text NOT NULL,entry_point text NOT NULL,idempotent boolean NOT NULL DEFAULT false,UNIQUE(id,tenant_id),UNIQUE(tenant_id,plugin_version_id,capability_key),FOREIGN KEY(plugin_version_id,tenant_id) REFERENCES plugin_version(id,tenant_id),FOREIGN KEY(category_id,tenant_id) REFERENCES capability_category(id,tenant_id));
CREATE TABLE plugin_dependency(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plugin_version_id uuid NOT NULL,dependency_kind text NOT NULL,target_id text NOT NULL,version_range text NOT NULL,UNIQUE(id,tenant_id),UNIQUE(tenant_id,plugin_version_id,dependency_kind,target_id),FOREIGN KEY(plugin_version_id,tenant_id) REFERENCES plugin_version(id,tenant_id));
CREATE TABLE plugin_entry_point(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,capability_id uuid NOT NULL,contract_ref text NOT NULL,timeout_ms integer,idempotency_mode text NOT NULL,UNIQUE(id,tenant_id),UNIQUE(tenant_id,capability_id),FOREIGN KEY(capability_id,tenant_id) REFERENCES capability_declaration(id,tenant_id));
CREATE TABLE manifest_signature(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plugin_version_id uuid NOT NULL,digest text NOT NULL,signature_ref text NOT NULL,provenance jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,plugin_version_id,digest),FOREIGN KEY(plugin_version_id,tenant_id) REFERENCES plugin_version(id,tenant_id));
CREATE TABLE validation_finding(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plugin_version_id uuid NOT NULL,finding_type text NOT NULL,severity text NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'open',reviewed_by uuid,reviewed_at timestamptz,UNIQUE(id,tenant_id),FOREIGN KEY(plugin_version_id,tenant_id) REFERENCES plugin_version(id,tenant_id));
CREATE TABLE installation_eligibility(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plugin_version_id uuid NOT NULL,target_scope text NOT NULL,eligible boolean NOT NULL,reasons jsonb NOT NULL,decided_by uuid NOT NULL,decided_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,plugin_version_id,target_scope),FOREIGN KEY(plugin_version_id,tenant_id) REFERENCES plugin_version(id,tenant_id));
CREATE TABLE plugin_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,plugin_id uuid,actor_id uuid NOT NULL,action text NOT NULL,detail jsonb NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),FOREIGN KEY(plugin_id,tenant_id) REFERENCES plugin(id,tenant_id));
CREATE INDEX idx_plugin_discovery ON plugin(tenant_id,status,classification); CREATE INDEX idx_capability_discovery ON capability_declaration(tenant_id,category_id,capability_key); CREATE INDEX idx_validation_open ON validation_finding(tenant_id,status,severity);
CREATE OR REPLACE FUNCTION prevent_plugin_self_approval() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.reviewed_by IS NOT NULL AND NEW.reviewed_by=NEW.submitted_by THEN RAISE EXCEPTION 'publisher submitter cannot approve own version'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_plugin_self_approval BEFORE INSERT OR UPDATE ON plugin_version FOR EACH ROW EXECUTE FUNCTION prevent_plugin_self_approval();
CREATE OR REPLACE FUNCTION protect_plugin_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (TG_TABLE_NAME='plugin_publisher' AND OLD.status='verified') OR (TG_TABLE_NAME='plugin' AND OLD.status IN('published','retired')) OR (TG_TABLE_NAME='plugin_version' AND OLD.status IN('published','rejected','retired')) OR (TG_TABLE_NAME='capability_category' AND OLD.status='active') OR (TG_TABLE_NAME='capability_declaration' AND EXISTS(SELECT 1 FROM plugin_version v WHERE v.id=OLD.plugin_version_id AND v.tenant_id=OLD.tenant_id AND v.status IN('published','retired'))) OR (TG_TABLE_NAME='plugin_dependency' AND EXISTS(SELECT 1 FROM plugin_version v WHERE v.id=OLD.plugin_version_id AND v.tenant_id=OLD.tenant_id AND v.status IN('published','retired'))) OR (TG_TABLE_NAME='plugin_entry_point' AND EXISTS(SELECT 1 FROM capability_declaration c JOIN plugin_version v ON v.id=c.plugin_version_id AND v.tenant_id=c.tenant_id WHERE c.id=OLD.capability_id AND c.tenant_id=OLD.tenant_id AND v.status IN('published','retired'))) OR TG_TABLE_NAME IN('manifest_signature','installation_eligibility','plugin_audit') OR (TG_TABLE_NAME='validation_finding' AND OLD.status='reviewed') THEN RAISE EXCEPTION 'governed plugin record is immutable at its declared lifecycle state'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_publisher_immutable BEFORE UPDATE OR DELETE ON plugin_publisher FOR EACH ROW EXECUTE FUNCTION protect_plugin_record(); CREATE TRIGGER trg_plugin_immutable BEFORE UPDATE OR DELETE ON plugin FOR EACH ROW EXECUTE FUNCTION protect_plugin_record(); CREATE TRIGGER trg_version_immutable BEFORE UPDATE OR DELETE ON plugin_version FOR EACH ROW EXECUTE FUNCTION protect_plugin_record(); CREATE TRIGGER trg_category_immutable BEFORE UPDATE OR DELETE ON capability_category FOR EACH ROW EXECUTE FUNCTION protect_plugin_record(); CREATE TRIGGER trg_capability_immutable BEFORE UPDATE OR DELETE ON capability_declaration FOR EACH ROW EXECUTE FUNCTION protect_plugin_record(); CREATE TRIGGER trg_dependency_immutable BEFORE UPDATE OR DELETE ON plugin_dependency FOR EACH ROW EXECUTE FUNCTION protect_plugin_record(); CREATE TRIGGER trg_entrypoint_immutable BEFORE UPDATE OR DELETE ON plugin_entry_point FOR EACH ROW EXECUTE FUNCTION protect_plugin_record(); CREATE TRIGGER trg_signature_immutable BEFORE UPDATE OR DELETE ON manifest_signature FOR EACH ROW EXECUTE FUNCTION protect_plugin_record(); CREATE TRIGGER trg_finding_immutable BEFORE UPDATE OR DELETE ON validation_finding FOR EACH ROW EXECUTE FUNCTION protect_plugin_record(); CREATE TRIGGER trg_eligibility_immutable BEFORE UPDATE OR DELETE ON installation_eligibility FOR EACH ROW EXECUTE FUNCTION protect_plugin_record(); CREATE TRIGGER trg_plugin_audit_immutable BEFORE UPDATE OR DELETE ON plugin_audit FOR EACH ROW EXECUTE FUNCTION protect_plugin_record();
ALTER TABLE plugin_publisher ENABLE ROW LEVEL SECURITY; ALTER TABLE plugin ENABLE ROW LEVEL SECURITY; ALTER TABLE plugin_version ENABLE ROW LEVEL SECURITY; ALTER TABLE capability_category ENABLE ROW LEVEL SECURITY; ALTER TABLE capability_declaration ENABLE ROW LEVEL SECURITY; ALTER TABLE plugin_dependency ENABLE ROW LEVEL SECURITY; ALTER TABLE plugin_entry_point ENABLE ROW LEVEL SECURITY; ALTER TABLE manifest_signature ENABLE ROW LEVEL SECURITY; ALTER TABLE validation_finding ENABLE ROW LEVEL SECURITY; ALTER TABLE installation_eligibility ENABLE ROW LEVEL SECURITY; ALTER TABLE plugin_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY plugin_publisher_tenant ON plugin_publisher USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY plugin_tenant ON plugin USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY plugin_version_tenant ON plugin_version USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY category_tenant ON capability_category USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY capability_tenant ON capability_declaration USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY dependency_tenant ON plugin_dependency USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY entrypoint_tenant ON plugin_entry_point USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY signature_tenant ON manifest_signature USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY validation_tenant ON validation_finding USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY eligibility_tenant ON installation_eligibility USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY plugin_audit_tenant ON plugin_audit USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid);
